<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserFederatedIdentity\Application\Usecase\Update;

use Psr\EventDispatcher\EventDispatcherInterface;
use Throwable;
use Civi\Lughauth\Shared\Security\Allow;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Shared\Exception\NotFoundException;
use Civi\Lughauth\Features\Access\UserFederatedIdentity\Domain\UserFederatedIdentityRef;
use Civi\Lughauth\Features\Access\UserFederatedIdentity\Application\Service\Visibility\UserFederatedIdentityVisibilityService;
use Civi\Lughauth\Features\Access\UserFederatedIdentity\Domain\Gateway\UserFederatedIdentityCommandRepositoryGateway;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class UserFederatedIdentityUpdateUsecase
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly EventDispatcherInterface $dispatcher,
        private readonly UserFederatedIdentityVisibilityService $visibility,
        private readonly UserFederatedIdentityCommandRepositoryGateway $writer,
    ) {
    }

    public function allowUpdate(?UserFederatedIdentityRef $ref = null): Allow
    {
        $this->logDebug("Check allow update usecase for User federated identity");
        $span = $this->startSpan("Check allow update usecase for User federated identity");
        try {
            $result = $this->dispatcher->dispatch(new UserFederatedIdentityUpdateAllowDecision(Allow::allowed('update', 'Allowed to update by default')));
            return $result->getAllow();
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function fixedFields(?UserFederatedIdentityRef $ref = null): array
    {
        $this->logDebug("Check fixed fields for update usecase for User federated identity");
        $span = $this->startSpan("Check fixed fields for update usecase for User federated identity");
        try {
            return $this->visibility->fieldsToFix($ref);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function update(string $uid, UserFederatedIdentityUpdateParams $params): UserFederatedIdentityUpdateResult
    {
        $this->logDebug("Run update usecase for User federated identity");
        $span = $this->startSpan("Run update usecase for User federated identity");
        try {
            $ref = new UserFederatedIdentityRef($uid);
            $allow = $this->allowUpdate($ref);
            if (!$allow->allowed) {
                throw new UnauthorizedException($allow->reason ?? 'Not allowed to update User federated identity');
            }
            if (!$original = $this->visibility->retrieveVisibleForUpdate($ref)) {
                throw new NotFoundException($uid);
            }
            $this->dispatcher->dispatch(new UserFederatedIdentityUpdateCheck($params, $original));
            $attributes = $this->visibility->copyWithFixed($params->toAttributes());
            $enriched = $this->dispatcher->dispatch(new UserFederatedIdentityUpdateEnrich($params, $original, $attributes));
            $input = $enriched->getEnrichedAttributes();
            $modified = $original->update($input);
            $result = $this->writer->update($original, $modified);
            $output = $this->visibility->copyWithHidden($this->visibility->prepareVisibleData($result));
            return new UserFederatedIdentityUpdateResult($output);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
